    'help' => [
        'page_title' => 'Service Desk - Aufgaben-Leitfaden',
        'guide' => 'Leitfaden',
        'nav_overview' => 'Überblick',
        'nav_board' => 'Das Board',
        'nav_list' => 'Listenansicht',
        'nav_calendar' => 'Kalenderansicht',
        'nav_timeline' => 'Zeitleistenansicht',
        'nav_table' => 'Tabellenansicht',
        'nav_panel' => 'Das Aufgabenpanel',
        'nav_tags' => 'Schlagwörter',
        'nav_evidence' => 'Verlauf und Nachweis',
        'evidence_heading' => 'Verlauf und Nachweis',
        'evidence_intro' => 'Jede Aufgabe führt einen Verlauf, und jede wiederkehrende Aufgabe hat einen Nachweisbericht: den Datensatz, den ein Auditor verlangt, wenn er sagt &ldquo;zeigen Sie mir, dass diese Prüfung dieses Jahr jeden Monat durchgeführt wurde&rdquo;.',
        'evidence_history_heading' => 'Der Verlauf einer Aufgabe',
        'case_report_heading' => 'Ein Fallbericht für eine Aufgabe',
        'case_report_body' => 'Die Schaltfläche <strong>Dokument</strong> oben im Aufgabenfenster öffnet die Aufgabe und ihre Teilaufgaben als einen druckbaren Bericht - Details, Beschreibung, Checklistenergebnisse, Formulare, befolgte Verfahren, Folgemaßnahmen, Kommentare, Verlauf und die angehängten Dateien. Wählen Sie <strong>Drucken</strong>, dann <em>Als PDF speichern</em>. Eine Aufgabe, die zu einem Ticket gehört, wird meist besser über den <strong>Export</strong> des Tickets berichtet, der auch die Unterhaltung einschließt. Das Drucken wird im Verlauf der Aufgabe protokolliert.',
        'evidence_history_body' => 'Der Tab <strong>Verlauf</strong> im Aufgabenfenster listet alles auf, was mit der Aufgabe geschehen ist, das Neueste zuerst: wer sie erstellt hat (eine Person oder <em>die Wiederholung</em>), jede Statusänderung, <strong>wer sie abgeschlossen hat</strong> und das Fälligkeitsdatum in diesem Moment, Wiedereröffnung, Änderungen von Fälligkeitsdatum, Startdatum und Zuweisung, ein Überspringen samt Grund, angehängte und entfernte Checklisten sowie jedes Abhaken, Entfernen des Hakens, jeden Wert und jedes Ergebnis bei den Schritten der Checkliste. Änderungen nach dem Abschluss der Aufgabe sind als solche gekennzeichnet. Nichts davon lässt sich bearbeiten oder löschen, und es bleibt auch dann erhalten, wenn die Aufgabe gelöscht wird.',
        'evidence_history_note' => 'Der Verlauf beginnt an dem Tag, an dem dies Ihrer FreeITSM-Installation hinzugefügt wurde. Alles davor - zum Beispiel wer eine ältere Aufgabe abgeschlossen hat - wurde nie erfasst, und der Bericht sagt <em>nicht erfasst</em>, statt zu raten.',
        'evidence_report_heading' => 'Der Nachweisbericht',
        'evidence_report_body' => 'Öffnen Sie ihn über eine wiederkehrende Aufgabe (<strong>Wiederholung &rarr; Ausführungsverlauf</strong>) oder über <strong>Aufgaben &rarr; Nachweis</strong>, das alle wiederkehrenden Aufgaben auflistet - auch gestoppte und solche, deren Aufgaben alle gelöscht wurden. Wählen Sie einen Zeitraum <em>geplanter</em> Termine. Jede Durchführung, die hätte stattfinden sollen, erhält eine Zeile mit ihrem Ergebnis, wer sie abgeschlossen hat, ihren Checklistenergebnissen und etwaigen Ausnahmen:',
        'evidence_outcome_on_time' => '<strong>Pünktlich</strong> - am oder vor dem ursprünglichen Fälligkeitsdatum (dem Datum, für das die Wiederholung sie erstellt hat) und einem etwaigen späteren Datum, auf das sie verschoben wurde, abgeschlossen.',
        'evidence_outcome_rescheduled' => '<strong>Pünktlich nach Verschiebung</strong> - nach dem ursprünglichen Fälligkeitsdatum abgeschlossen, aber am oder vor dem Datum, auf das sie zu diesem Zeitpunkt verschoben war. Fällig am 1., verschoben auf den 8., erledigt am 7. ist ein solcher Fall - niemals einfach Pünktlich.',
        'evidence_outcome_late' => '<strong>Verspätet</strong> - nach dem zu diesem Zeitpunkt geltenden Fälligkeitsdatum abgeschlossen.',
        'evidence_outcome_open' => '<strong>Offen</strong> und <strong>Überfällig</strong> - noch nicht abgeschlossen, vor beziehungsweise nach dem Fälligkeitsdatum.',
        'evidence_outcome_skipped' => '<strong>Übersprungen</strong> - absichtlich geschlossen, mit angegebenem Grund.',
        'evidence_outcome_missing' => '<strong>Fehlend</strong> - sie sollte existieren und tut es nicht. Bei einem festen Zeitplan ein Datum, das die Regel erzeugt hat, ohne Durchführung. Nach Abschluss nie, bevor die vorherige erledigt ist - aber sobald ein Abschluss oder Überspringen die nächste fällig gemacht hat, ist eine nächste, die nie erschienen ist, fehlend.',
        'evidence_outcome_removed' => '<strong>Entfernt</strong> - erstellt, dann gelöscht. Ihre Checklistenergebnisse, Ausnahmen und ihr Verlauf bleiben erhalten und werden angezeigt.',
        'evidence_flags' => 'Neben dem Ergebnis gibt es Kennzeichen: <strong>Verschoben</strong> (das Fälligkeitsdatum wurde vor dem Abschluss verschoben), <strong>Fälligkeitsdatum nach Abschluss geändert</strong> (das ändert nie das Ergebnis), <strong>Verspätet erstellt</strong> (der Planer hat sie erstellt, nachdem die Arbeit hätte beginnen sollen) und <strong>Nach Abschluss geändert</strong> (ein Checklistenschritt wurde geändert, nachdem er erledigt war). Zeiten werden in der Zeitzone der Installation angezeigt, und ein Fälligkeitsdatum ist dort ein Kalendertag.',
        'evidence_why' => 'Für eine fehlende oder verspätete Durchführung ergänzt der Bericht, was der Laufverlauf des Jobs für wiederkehrende Aufgaben für diese Zeit zeigt (siehe Reporting &rarr; Systemprotokolle &rarr; Hintergrundjobs): <em>kein erfasster Lauf</em>, <em>der Job ist fehlgeschlagen</em> mit seiner Meldung oder <em>durch einen Nachholauf erstellt</em>. Er sagt nie, dass der Job nicht lief - nur, was erfasst wurde - und sagt <em>nicht verfügbar</em> für eine Zeit vor der Erfassung des Laufverlaufs. Das Ansehen oder Exportieren des Berichts erstellt nie eine Aufgabe.',
        'evidence_skip_heading' => 'Eine Durchführung überspringen',
        'evidence_skip_body' => 'Wenn eine Durchführung einer Wiederholung nicht stattfinden soll - etwa weil der geprüfte Server gerade ersetzt wurde -, verwenden Sie <strong>Wiederholung &rarr; Überspringen</strong> und geben Sie den Grund an. Sie wird als <em>übersprungen</em>, nicht als erledigt geschlossen, und zwar in den unter Einstellungen &rarr; Nachweis gewählten Status; der Bericht zeigt sie mit dem Grund. Eine Wiederholung, die sich nach Abschluss wiederholt, erstellt ihre nächste Durchführung, als wäre sie abgeschlossen worden.',
        'evidence_results_heading' => 'Bestanden, Nicht bestanden und Nicht zutreffend',
        'evidence_results_body' => 'Ein Checklistenschritt kann statt eines Hakens ein <strong>Ergebnis</strong> verlangen: Schalten Sie im Modul Checklisten bei dem Schritt <strong>Ergebnis abfragen</strong> ein. An einer Aufgabe zeigt er dann <strong>Bestanden</strong>, <strong>Nicht bestanden</strong> und <strong>Nicht zutreffend</strong>, und bei Nicht bestanden wird vor dem Speichern gefragt, was schiefgelaufen ist. Die Aufgabe kann trotzdem mit einem nicht bestandenen Schritt abgeschlossen werden - der Bericht zeigt ihn als <strong>Ausnahme</strong>, sodass eine abgeschlossene Aufgabe nie eine Kontrolle verbirgt, die nicht bestanden wurde. Schritte ohne diese Option behalten ihren Haken, und Tickets verwenden immer den Haken. Das Speichern einer Checklistenvorlage bewahrt die vorherige Version auf, und jede Aufgabe erfasst die Version, die sie erhalten hat.',
        'evidence_export_heading' => 'Drucken und Exportieren',
        'evidence_export_body' => '<strong>Drucken</strong> öffnet den Bericht bereit für <em>Drucken &rarr; Als PDF speichern</em>. Vier CSV-Dateien - Durchführungen, Checklistenergebnisse, Anhänge und Kommentare sowie Formularantworten - verwenden dieselben Aufgaben-IDs und lassen sich daher in einer Tabellenkalkulation verbinden. Jedes Drucken und jeder Export wird im Bericht protokolliert, mit Person und Zeitpunkt.',
        'evidence_auditor_heading' => 'Eine Auditor-Rolle',
        'evidence_auditor_body' => 'Geben Sie jemandem <strong>Nur-Lese-Zugriff</strong> auf Aufgaben (System &rarr; Analysten oder Teams &rarr; Modulzugriff) und, falls Einstellungen &rarr; Nachweis den Bericht einschränkt, eine Rolle mit <strong>Nachweisbericht ausführen</strong>. Diese Person kann jede Aufgabe öffnen, die ihre Unternehmen zulassen, deren Verlauf lesen und den Nachweis drucken oder exportieren, aber nichts erstellen, ändern, abschließen, überspringen oder löschen. Damit sie die Antworten auf Formulare dieser Aufgaben lesen kann, ohne das Modul Formulare zu erhalten, fügen Sie ihrer Rolle <strong>Formularantworten an Aufgaben lesen, die Sie sehen können</strong> hinzu.',
        'work_heading' => 'Die Arbeitsansicht',
        'work_body' => 'Eine Aufgabe mit Arbeitsmaterial - Checklisten, Formularen oder Verfahren - hat einen Abschnitt <strong>Arbeit</strong>, der alles zusammenführt: wofür die Aufgabe da ist und für welchen Tag, den Fortschritt (<em>3 von 5 erledigt</em>, gezählt über Checklistenschritte und erforderliche Formulare), die Anweisungen, ihre Verfahren, ihre Checklisten und ihre Formulare - und <strong>Abschließen</strong>, was dieselben Fragen stellt wie das Statusfeld. Im Tab-Layout des großen Fensters ist es der Tab <strong>Arbeit</strong>, und eine Aufgabe mit Arbeitsinhalt öffnet sich dort - entfernen Sie den Haken bei <em>Hier öffnen</em> im Tab, wenn Sie das nicht möchten; im zweispaltigen Layout steht es in der breiten Spalte; im Seitenbereich steht es in einer Zeile.',
        'work_procedures' => 'Ist <strong>Verfahren an Aufgaben</strong> eingeschaltet (Einstellungen &rarr; Checklisten), kann eine Aufgabe <strong>Wissensartikel</strong> als ihr Verfahren referenzieren, die direkt dort gelesen werden. Jeder folgt dem eigenen Zugriff von Wissen: Wer einen Artikel nicht lesen darf, sieht, dass es ein Verfahren gibt, aber nicht, was darin steht. Die Durchführungen einer wiederkehrenden Aufgabe folgen jeweils denselben Verfahren. Wird eine Durchführung abgeschlossen, wird der Text jedes Artikels <em>in seinem damaligen Stand</em> mit ihr aufbewahrt, sodass eine spätere Bearbeitung des Artikels nie umschreibt, wonach die Arbeit erledigt wurde - der Nachweisbericht listet diesen Text einmal unter <strong>Verwendete Verfahren</strong> auf.',
        'work_followups' => '<strong>Folgemaßnahmen</strong>: Wenn eine Prüfung etwas zu beheben findet, erstellen Sie in der Arbeitsansicht dafür eine <strong>Aufgabe</strong> oder ein <strong>Ticket</strong> - <em>Nachverfolgen</em> bei einem fehlgeschlagenen Schritt oder einem eingereichten Formular füllt die Herkunft aus - oder verknüpfen Sie eine bereits vorhandene. Jede zeigt, ob sie noch offen ist. Der Abschluss der Prüfung wartet nicht auf die Behebung, es sei denn, Einstellungen &rarr; Nachweis legt das fest: Standardmäßig kann die Prüfung abgeschlossen sein, während die Behebung weiterläuft. Ein Folge-Ticket wird von Ihnen als Anforderer erstellt, wie jedes Ticket, das Sie von Hand erstellen.',
        'work_period' => '<strong>Wiederkehrende Prüfungen</strong> können angeben, was jede Durchführung abdeckt und wann sie fällig ist: <em>Jede Durchführung prüft</em> den Tag, für den sie vorgesehen ist, den Vortag (die Backups der letzten Nacht) oder alles seit der vorherigen; <em>Jede Durchführung ist fällig</em> am selben Tag, einige Tage später oder am nächsten Arbeitstag. Eine Prüfung vom Samstag, die am Montag fällig ist und am Montag erledigt wird, ist im Nachweisbericht <strong>pünktlich</strong>; am Dienstag erledigt, ist sie verspätet. In einem Formular kann im Formulardesigner eine Auswahlmöglichkeit als <strong>Ausnahme</strong> markiert werden - Warnung, Fehler - und ihre Wahl führt die Antwort im Nachweisbericht unter den Ausnahmen der Durchführung auf.',
        'forms_heading' => 'Formulare, die eine Aufgabe braucht',
        'forms_body' => 'Ist <strong>Formulare an Aufgaben</strong> eingeschaltet (Einstellungen &rarr; Checklisten), kann eine Aufgabe Formulare aus dem Modul Formulare verlangen - etwa eine tägliche Backup-Prüfung mit OK / Warnung / Fehler und einer Erklärung. Fügen Sie eines unter <strong>Formulare</strong> im Aufgabenfenster hinzu und wählen Sie <strong>Erforderlich</strong> (die Aufgabe kann erst abgeschlossen werden, wenn es eingereicht ist), <strong>Erforderlich (warnen)</strong> (sie kann es, und das wird protokolliert) oder <strong>Optional</strong>. Bei einer wiederkehrenden Aufgabe braucht jede neue Durchführung dieselben Formulare, unbeantwortet - frühere Antworten werden nie übernommen.',
        'forms_fill' => '<strong>Ausfüllen</strong> öffnet das Formular für diese Durchführung direkt in der Arbeitsansicht, mit allen Fragen, Bedingungen und Prüfungen (<em>In neuem Tab öffnen</em> gibt ihm eine eigene Seite). <strong>Entwurf speichern</strong> bewahrt es für später auf, und der Entwurf gehört zur Durchführung, sodass ihn eine Kollegin oder ein Kollege weiterführen kann; die Aufgabe zeigt, wer zuletzt gespeichert hat. Wenn jemand anderes speichert, während Sie es geöffnet haben, wird nichts überschrieben: Sie erfahren, wer und wann, Ihre Antworten bleiben auf dem Bildschirm, und Sie entscheiden, ob Sie die anderen übernehmen oder Ihre behalten. <strong>Einreichen</strong> verknüpft die Antworten mit dieser Durchführung - ohne Referenznummern zum Kopieren - und <strong>Korrigieren</strong> ersetzt sie später, wobei die frühere Einreichung im Datensatz erhalten bleibt.',
        'forms_complete' => 'Der Abschluss der Aufgabe prüft ihre erforderlichen Formulare genauso, wie er Checklistenschritte prüft, gleichgültig wie sie abgeschlossen wird - über das Statusfeld, durch Ziehen der Karte, durch Abhaken einer Teilaufgabe oder über die API. Abschließen bedeutet, dass die Prüfung durchgeführt und erfasst wurde: Eine Antwort mit Warnung oder Fehler bleibt im Nachweisbericht genau das; er listet die Formulare und Antworten jeder Durchführung auf und hat eine <strong>CSV Formularantworten</strong>.',
        'forms_access' => 'Das Ausfüllen eines Formulars in einer Aufgabe erfordert Zugriff auf Formulare, wie auf der Seite Formulare. Das Lesen der Antworten erfordert Zugriff auf Formulare <em>oder</em> die Rollenberechtigung <strong>Formularantworten an Aufgaben lesen, die Sie sehen können</strong> - die Aufgabe sehen zu können, reicht allein nicht aus. Ohne beides sehen Sie, dass ein Formular eingereicht wurde, von wem und wann, aber nicht seine Antworten - im Aufgabenfenster, im Nachweisbericht und in dessen CSV gleichermaßen.',
        'forms_note' => 'Eine für eine Aufgabe vorgenommene Einreichung ist der Datensatz dieser Durchführung und kann daher nicht aus dem Modul Formulare gelöscht werden; ein Formular mit solchen Einreichungen kann ebenfalls nicht gelöscht werden - setzen Sie es stattdessen auf inaktiv. In einer Installation mit mehreren Unternehmen wird sie nur Personen angezeigt, die diese Aufgabe sehen können.',
        'nav_settings' => 'Einstellungen',
        'nav_tips' => 'Schnelltipps',
        'nav_companies' => 'Unternehmen',
        'companies_heading' => 'Aufgaben und Unternehmen',
        'companies_intro' => 'Zu welchem Kunden eine Aufgabe gehört und wie Sie eine verschieben, die unter dem falschen Unternehmen abgelegt wurde.',
        'companies_scope' => 'Jede Aufgabe gehört zu genau einem Unternehmen. Eine aus einem Ticket erstellte Aufgabe übernimmt das Unternehmen dieses Tickets; eine selbst angelegte das Unternehmen, in dem Sie gerade arbeiten. Sie sehen immer nur Aufgaben von Unternehmen, auf die Sie Zugriff haben.',
        'companies_move' => 'Beim falschen Kunden abgelegt? Klicken Sie mit der rechten Maustaste auf die Aufgabe und wählen Sie <strong>In Unternehmen verschieben</strong> — im Board, in der Tabelle oder in der Zeitleiste. Sie können eine Aufgabe nur in ein Unternehmen verschieben, auf das Sie selbst Zugriff haben, und die Verschiebung wird im Verlauf der Aufgabe festgehalten, sodass nachvollziehbar ist, was wann verschoben wurde.',
        'companies_subtasks' => 'Teilaufgaben werden zusammen mit ihrer übergeordneten Aufgabe auf einmal verschoben. Eine Teilaufgabe lässt sich nicht einzeln verschieben, da sie immer zum selben Unternehmen gehört wie die Aufgabe über ihr — eine Trennung würde eine übergeordnete Aufgabe mit einer Teilaufgabe zurücklassen, die ein Teil Ihrer Mitarbeitenden nicht sehen könnte.',
        'companies_links' => 'Eine mit einem Ticket oder einem Change verknüpfte Aufgabe lässt sich nicht davon wegverschieben; Ihnen wird angezeigt, welche Verknüpfung im Weg ist, sodass Sie sie entfernen oder den anderen Datensatz ebenfalls verschieben können. Eine Verknüpfung mit einem Vertrag verhindert eine Verschiebung nie, da Verträge nicht unter einem einzelnen Unternehmen abgelegt sind.',
        'hero_title' => 'Leitfaden zum Aufgabenmodul',
        'hero_subtitle' => 'Planen Sie interne Arbeit, weisen Sie sie zu und behalten Sie sie auf einem Kanban-Board im Blick &mdash; mit Kalender, Zeitleiste, Schlagwörtern und Spalten je Status.',
        'overview_heading' => 'Überblick',
        'overview_intro' => 'Das Aufgabenmodul ist ein schlankes Arbeits-Tracking-Tool für Ihr Service-Desk-Team. Nutzen Sie es für die Arbeiten, die keine Tickets sind &mdash; Projektarbeit, interne Verwaltung, wiederkehrende Aufgaben, Nachfassaktionen &mdash; und sehen Sie sie als Kanban-Board, sortierbare Liste, Kalender, Gantt-artige Zeitleiste oder als vollbildschirmfüllende, bearbeitbare Tabelle. Aufgaben können mit Tickets und Änderungen verknüpft werden, Schlagwörter tragen und in Teilaufgaben aufgeteilt werden.',
        'overview_card1_title' => 'Board',
        'overview_card1_desc' => 'Ein Kanban-Board mit einer Spalte je Status. Ziehen Sie Karten zwischen Spalten, um den Status zu ändern, ziehen Sie Spaltenüberschriften, um sie neu anzuordnen, und fügen Sie Aufgaben per Schnellerfassung direkt in eine Spalte ein.',
        'overview_card2_title' => 'Listenansicht',
        'overview_card2_desc' => 'Dieselben Aufgaben als sortierbare Tabelle &mdash; klicken Sie auf eine Spaltenüberschrift, um nach Titel, Status, Priorität, Zugewiesen an, Team oder Fälligkeitsdatum zu sortieren.',
        'overview_card3_title' => 'Kalender',
        'overview_card3_desc' => 'Ein Monatsraster, das Aufgaben nach Fälligkeitsdatum einordnet. Mehrtägige Aufgaben können als einzelner Chip, als durchgehender Balken oder als Chip an jedem Tag angezeigt werden &mdash; Ihre Wahl in den Einstellungen.',
        'overview_card4_title' => 'Zeitleiste',
        'overview_card4_desc' => 'Ein Gantt-artiges Diagramm, das jede Aufgabe als Balken vom Start- bis zum Fälligkeitsdatum zeigt. Ziehen Sie Balken, um sie zu verschieben, und ziehen Sie an den Rändern, um Start- und Fälligkeitsdatum festzulegen.',
        'overview_card5_title' => 'Tabelle',
        'overview_card5_desc' => 'Excel-artiges Raster mit Bearbeitung direkt in der Zelle &mdash; passen Sie Status, Priorität, Zugewiesen an, Team oder Termine direkt in der Zeile an. Spalten, Sortierung, Filter und Suche bleiben je Analyst erhalten.',
        'overview_card6_title' => 'Schlagwörter',
        'overview_card6_desc' => 'Mehrfach vergebbare Bezeichnungen für übergreifende Themen &mdash; Sicherheit, ISO, Umwelt &mdash; nach denen Sie filtern und suchen können.',
        'overview_card7_title' => 'Einstellungen',
        'overview_card7_desc' => 'Konfigurieren Sie Status, Prioritäten und Schlagwörter; steuern Sie, wie der Kalender mehrtägige Aufgaben darstellt und was jede Karte anzeigt.',
        'overview_tip' => 'Board, Liste, Kalender und Zeitleiste sind nur unterschiedliche Ansichten derselben Aufgaben. Eine Änderung in einer Ansicht wirkt sich auf alle anderen aus.',
        'board_heading' => 'Das Board',
        'board_intro' => 'Das Board ist die Standardansicht &mdash; ein Kanban-Layout mit einer Spalte je Status. Es ist die schnellste Möglichkeit, den Stand aller Arbeiten zu sehen und sie voranzubringen.',
        'board_columns_heading' => 'Spalten sind Status',
        'board_columns_body' => 'Jede Spalte ist ein Status, der unter Einstellungen &rarr; Status definiert ist, angezeigt in Anzeigereihenfolge mit der Statusfarbe als Punkt in der Kopfzeile. Fügen Sie einen Status hinzu, und er wird zu einer Spalte; es gibt kein eigenes "Spalten"-Konzept zu verwalten. Um die Spalten neu anzuordnen, <strong>ziehen Sie einfach eine Spaltenüberschrift</strong> nach links oder rechts &mdash; die neue Reihenfolge wird gespeichert.',
        'board_creating_heading' => 'Aufgaben erstellen',
        'board_creating_step1' => '<strong>Klicken Sie auf das + in einer Spaltenüberschrift</strong> &mdash; oben in dieser Spalte öffnet sich ein Eingabefeld.',
        'board_creating_step2' => '<strong>Geben Sie einen Titel ein und drücken Sie die Eingabetaste</strong> &mdash; die Aufgabe wird mit dem Status dieser Spalte erstellt und Ihnen zugewiesen. Klicken Sie jederzeit darauf, um den Rest auszufüllen.',
        'board_moving_heading' => 'Verschieben und neu anordnen',
        'board_moving_body' => 'Ziehen Sie eine Karte in eine andere Spalte, um ihren Status zu ändern; ziehen Sie sie innerhalb einer Spalte nach oben oder unten, um sie neu anzuordnen. Eine violette Linie zeigt, wo sie landen wird. Wird eine Karte in einen als <em>Geschlossen</em> markierten Status abgelegt, wird der Abschlusszeitpunkt automatisch vermerkt.',
        'board_rightclick_heading' => 'Rechtsklick auf eine Karte',
        'board_rightclick_body' => 'Ein Rechtsklick auf eine Karte öffnet ein Schnellaktionsmenü &mdash; weisen Sie einen Analysten oder ein Team zu, ändern Sie Status oder Priorität, oder erstellen Sie eine Teilaufgabe &mdash;, ohne die Karte überhaupt zu öffnen.',
        'board_search_heading' => 'Suche und Filter',
        'board_search_body' => 'Die Seitenleiste enthält ein <strong>Suchfeld</strong> (filtert während der Eingabe nach Titel und Beschreibung &mdash; und nach Schlagwörtern, falls aktiviert) sowie Filter für <strong>Meine Aufgaben / Alle Aufgaben</strong>, <strong>Team</strong>, <strong>Analyst</strong> und, falls aktiviert, <strong>Schlagwort</strong>. Filter und Suche gelten auch für die Listenansicht. Aktivieren Sie <strong>Erledigte ausblenden</strong>, um jede Aufgabe in einem geschlossenen Status auszublenden - im Board werden dadurch auch die Spalten Erledigt ausgeblendet. Die Einstellung wird für Sie gespeichert, und eine erledigte Aufgabe wird nie als <em>Überfällig</em> angezeigt.',
        'board_subtasks' => 'Die Teilaufgaben einer Aufgabe werden unter ihrer Karte aufgelistet - klicken Sie auf eine, um sie zu öffnen. Ziehen Sie innerhalb einer Aufgabe eine Teilaufgabe am Griff <strong>&#8942;&#8942;</strong>, um die Reihenfolge zu ändern. Unter <strong>Teilaufgaben auf Karten</strong> in der Seitenleiste legen Sie fest, welche Teilaufgaben die Karten auflisten: <strong>Alle</strong>, <strong>Offene</strong> (nur die noch offenen) oder <strong>Keine</strong> (nur die Anzahl). Klicken Sie auf die Zahl einer Karte, etwa <strong>1/4</strong>, um die Teilaufgaben nur dieser Karte unabhängig von der Einstellung ein- oder auszublenden. Beides wird für Sie gespeichert.',
        'board_card_order' => 'Verwenden Sie <strong>Kartenreihenfolge</strong> im linken Bereich, um festzulegen, wie die Karten in jeder Spalte angeordnet sind. <strong>Manuell</strong> ist die Reihenfolge, in die die Karten gezogen wurden und die alle teilen. <strong>Fälligkeitsdatum</strong> stellt überfällige Arbeit nach vorn, dann heute fällige Arbeit, dann den Rest nach Datum, wobei Aufgaben ohne Fälligkeitsdatum unten stehen - nur für Sie und ohne die manuelle Reihenfolge zu ändern, die beim Zurückwechseln so wiederkommt, wie sie war. Bei Sortierung nach Fälligkeitsdatum können Sie eine Karte weiterhin in eine andere Spalte ziehen; um Karten innerhalb einer Spalte neu anzuordnen, wechseln Sie zu Manuell. Ihre Wahl wird gespeichert.',
        'board_columns_by_analyst' => 'Wählen Sie in der linken Leiste <strong>Spalten &rarr; Analyst</strong>, um stattdessen eine Spalte pro Person zu sehen (Ihre zuerst, dann <em>Nicht zugewiesen</em>), wobei jede Karte ihren Status zeigt. Wenn Sie eine Karte in die Spalte einer anderen Person ziehen, wird ihr die Aufgabe zugewiesen. Ihre Auswahl wird gespeichert.',
        'board_tip' => 'Legen Sie unter Einstellungen &rarr; Karte fest, was jede Karte anzeigt &mdash; Priorität, Zugewiesen an, Team, Termine, ein Beschreibungsauszug, Teilaufgaben-Fortschritt, Schlagwörter &mdash;, damit Sie Aufgaben überfliegen können, ohne sie zu öffnen.',
        'list_heading' => 'Listenansicht',
        'list_intro' => 'Die Liste ist das Datenpendant des Boards &mdash; dieselben Aufgaben als sortierbare Tabelle. Wechseln Sie mit dem Ansicht-Umschalter in der Seitenleiste dorthin.',
        'list_body' => 'Klicken Sie auf eine Spaltenüberschrift &mdash; Titel, Status, Priorität, Zugewiesen an, Team, Fällig &mdash;, um danach zu sortieren; klicken Sie erneut, um die Richtung umzukehren. Suche und Seitenleisten-Filter funktionieren genau wie beim Board, sodass Sie die Liste eingrenzen und dann das Übrige sortieren können. Klicken Sie auf eine Zeile, um die Aufgabe zu öffnen.',
        'list_tip' => 'Die Liste ist der richtige Ort, um eine Aufgabe zu finden, deren Status keine Board-Spalte hat (zum Beispiel ein eigener Status „Icebox“) &mdash; die Liste zeigt jede Aufgabe unabhängig vom Status.',
        'calendar_heading' => 'Kalenderansicht',
        'calendar_intro' => 'Der Kalender ordnet Aufgaben in einem Datumsraster an, damit Sie Fristen und Arbeitsaufkommen auf einen Blick sehen. Aufgaben sind entsprechend ihrem Status eingefärbt.',
        'calendar_body' => 'Die Symbolleiste enthält <strong>Heute</strong>, Zurück/Weiter sowie rechts einen Umschalter <strong>Monat / Woche / Tag</strong>. <em>Monat</em> ist das vertraute Raster mit 4&ndash;6 Wochen; <em>Woche</em> zoomt auf eine einzelne Sieben-Tage-Zeile, die den Bildschirm ausfüllt; <em>Tag</em> springt auf ein einzelnes Datum und listet jede an diesem Tag anfallende Aufgabe als Kartenzeile auf. Zurück/Weiter springt je nach aktiver Ansicht um einen Monat, eine Woche oder einen Tag.',
        'calendar_sidebar' => 'Die Seitenleiste zeigt eine Farblegende, dieselben Filter Meine/Alle/Team/Analyst wie das Board sowie ein Panel <strong>Anzeigemodus</strong> mit einem Ändern-Link direkt zu den Kalendereinstellungen.',
        'calendar_click_heading' => 'Auf eine Aufgabe klicken',
        'calendar_click_body' => 'Ein Klick auf einen Aufgaben-Chip, einen Balken oder eine Zeile der Tagesansicht öffnet rechts im Kalender ein seitlich einblendendes <strong>Schnellpanel</strong> &mdash; Sie bleiben, wo Sie sind. Titel, Status, Priorität, Zugewiesen an, Team und Termine sind alle im Panel bearbeitbar; das Öffnen-Symbol oben öffnet den vollständigen Editor im Dashboard, wenn Sie eine Rich-Text-Beschreibung, Teilaufgaben oder Kommentare benötigen.',
        'calendar_multiday_heading' => 'Wie mehrtägige Aufgaben dargestellt werden',
        'calendar_multiday_body' => 'Eine Aufgabe, deren Startdatum vor dem Fälligkeitsdatum liegt, erstreckt sich über mehrere Tage. Wie dieser Zeitraum angezeigt wird, wird einmal für die gesamte Installation unter Einstellungen &rarr; Kalender festgelegt:',
        'calendar_field_deadline' => '<strong>Fälligkeitsmarkierung</strong> &mdash; nur ein Chip am Fälligkeitsdatum. Die übersichtlichste Option; der gesamte Zeitraum bleibt in der Zeitleiste sichtbar.',
        'calendar_field_span' => '<strong>Durchgehender Balken</strong> &mdash; ein durchgehender Balken über den gesamten Zeitraum, der an den Wochenzeilen umbricht. Am besten geeignet, um die Dauer zu erkennen.',
        'calendar_field_everyday' => '<strong>Jeden Tag</strong> &mdash; ein Chip in jeder Tageszelle, die die Aufgabe abdeckt. Gründlich, aber lange Aufgaben können das Raster überfüllen.',
        'calendar_note' => 'Eine Aufgabe mit nur einem Fälligkeitsdatum wird immer als einzelner Chip an diesem Datum angezeigt, unabhängig vom gewählten Modus.',
        'timeline_heading' => 'Zeitleistenansicht',
        'timeline_intro' => 'Die Zeitleiste ist ein Gantt-artiges Diagramm. Jede Aufgabe ist ein waagerechter Balken vom Start- bis zum Fälligkeitsdatum, sodass Sie Überschneidungen, Lücken und Dauern erkennen können.',
        'timeline_body' => 'Eine Aufgabe mit nur einem Fälligkeitsdatum wird als eintägiger Balken angezeigt. Zeilen können nach <strong>Zugewiesen an</strong>, <strong>Status</strong> gruppiert oder flach angezeigt werden &mdash; wählen Sie dies in der Seitenleiste. Eine gestrichelte Markierung zeigt heute an, die Spalte mit dem Aufgabennamen und die Datumskopfzeile bleiben beim Scrollen stehen, und das Tagesraster passt sich automatisch dem Bildschirm an: kurze Zeiträume füllen die gesamte Breite aus, längere behalten für jeden Tag eine angenehme Größe und scrollen horizontal.',
        'timeline_drag_heading' => 'Balken ziehen, um sie zu verschieben',
        'timeline_drag_body' => 'Die Balken sind unmittelbar bearbeitbar. Fahren Sie mit der Maus über einen Balken, und an beiden Enden erscheinen durchscheinende Ziehpunkte:',
        'timeline_field_body' => '<strong>Den Balkenkörper ziehen</strong> &mdash; Start- und Fälligkeitsdatum verschieben sich um dieselbe Anzahl Tage. Die Aufgabe wandert als Ganzes, ohne dass sich die Dauer ändert.',
        'timeline_field_left' => '<strong>Den linken Rand ziehen</strong> &mdash; nur das Startdatum ändert sich. Nützlich, um den Beginn vorzuziehen oder zu verschieben, während die Frist unverändert bleibt.',
        'timeline_field_right' => '<strong>Den rechten Rand ziehen</strong> &mdash; nur das Fälligkeitsdatum ändert sich. Bei einer Aufgabe mit nur einer Frist (ohne gesetztes Startdatum) wird das alte Fälligkeitsdatum zum neuen Startdatum, sodass der Balken zu einem echten Zeitraum wird, statt an das neue Ende zu einer eintägigen Position zu springen.',
        'timeline_snap_note' => 'Beim Ziehen wird auf ganze Tage gerastet. Ein kurzer Klick auf einen Balken ohne Ziehbewegung öffnet weiterhin die Aufgabe &mdash; unterhalb einer Bewegungsschwelle von 3 Pixel wird dies als Klick, nicht als Ziehen gewertet.',
        'timeline_rightclick_heading' => 'Rechtsklick für Schnellaktionen',
        'timeline_rightclick_body' => 'Rechtsklicken Sie einen beliebigen Balken für dasselbe Kontextmenü wie beim Board &mdash; <strong>Analyst zuweisen</strong>, <strong>Team zuweisen</strong>, <strong>Status ändern</strong>, <strong>Priorität ändern</strong> &mdash;, ohne etwas zu öffnen. Jedes Untermenü markiert den aktuellen Wert der Aufgabe mit einem Häkchen.',
        'timeline_click_heading' => 'Auf einen Balken klicken',
        'timeline_click_body' => 'Ein einfacher Klick auf einen Balken (oder auf die Spalte mit dem Aufgabennamen links) öffnet rechts in der Zeitleiste dasselbe seitlich einblendende Schnellpanel wie im Kalender. Bearbeiten Sie die gängigen Felder direkt dort, oder klicken Sie auf das Öffnen-Symbol oben im Panel, um zum vollständigen Editor im Dashboard zu wechseln.',
        'table_heading' => 'Tabellenansicht',
        'table_intro' => 'Die Tabellenansicht ist ein vollbildschirmfüllendes, Excel-artiges Raster &mdash; eine Zeile je Aufgabe, mit bearbeitbaren Zellen. Hier lässt sich am schnellsten eine Liste sichten, Felder in großer Zahl anpassen oder genau das Spaltenlayout aufbauen, in dem Sie arbeiten möchten.',
        'table_edit_heading' => 'Direkt in der Zelle bearbeiten',
        'table_open_heading' => 'Eine Aufgabe öffnen',
        'table_open_body' => 'Jede Zeile beginnt mit einem <strong>Öffnen</strong>-Symbol (oder klicken Sie mit der rechten Maustaste auf eine Zeile und wählen Sie <strong>Öffnen</strong>). Es öffnet über der Tabelle denselben Bereich wie im Kalender und in der Zeitleiste, sodass Filter, Sortierung und Position erhalten bleiben. Der Bereich ist ein Schnellblick - Status, Daten, Zuweisung und Beschreibung - mit einer Schaltfläche <strong>Bearbeiten</strong>, die ihn gleich dort in die vollständige Aufgabe verwandelt; oder wählen Sie <strong>Die vollständige Aufgabe</strong> unter <strong>Einstellungen &rarr; Aufgabe öffnen</strong>, um immer die vollständige Aufgabe zu erhalten, wie auf dem Board. Das Start-Symbol oben führt zur Aufgabe auf dem Board. Klicken Sie mit Strg oder der mittleren Maustaste auf das Symbol, um die vollständige Aufgabe stattdessen in einem neuen Tab zu öffnen. Ein Klick auf eine Zelle bearbeitet sie weiterhin wie bisher.',
        'table_edit_body' => 'Die meisten Spalten zeigen statt reinem Text ein bearbeitbares Element. Wählen Sie einen neuen Status oder eine neue Priorität aus dem Dropdown, tauschen Sie den Zugewiesenen oder das Team aus, geben Sie einen neuen Titel ein, tippen oder wählen Sie ein neues Start-/Fälligkeitsdatum &mdash; jede Zelle speichert bei jeder Änderung, ohne dass Sie nach einer Speichern-Schaltfläche suchen müssen. Status und Priorität zeigen einen farbigen Punkt, der sich nach dem Speichern sofort aktualisiert.',
        'table_views_heading' => 'Gespeicherte Ansichten',
        'table_views_body' => 'Wenn die Tabelle so aussieht, wie Sie sie haben möchten &mdash; die richtigen Spalten, sortiert und gefiltert &mdash; speichert <strong>Ansicht speichern</strong> in der Symbolleiste diese Anordnung unter einem Namen, und <strong>Ansichten</strong> daneben öffnet die Bibliothek. Eine Ansicht kann für <strong>nur Sie</strong>, für <strong>eines Ihrer Teams</strong> oder für <strong>alle</strong> sichtbar sein; der Stern macht eine davon zu Ihrem Standard, sodass die Tabelle damit öffnet. Die Bibliothek lässt sich nach Name, Beschreibung oder Ersteller durchsuchen und als Liste oder als Karten anzeigen.',
        'table_views_note' => 'Spalten, Sortierung und Filter werden gespeichert, das Suchfeld bewusst nicht: Eine Suche ist eine einmal gestellte Frage und keine Art, Dinge anzusehen. Dieselben Ansichten gibt es in den Tabellen von Geräte, Kalender und Änderungsmanagement, jede mit ihren eigenen.',
        'table_columns_heading' => 'Spalten: anzeigen, ausblenden, neu anordnen',
        'table_columns_body' => 'Klicken Sie auf die Schaltfläche <strong>Spalten</strong> in der Symbolleiste, um ein Fenster mit allen Spalten zu öffnen, die die Tabelle kennt. Setzen Sie ein Häkchen bei den Spalten, die sichtbar sein sollen; ziehen Sie die Zeilen, um sie neu anzuordnen. Der Griff in einer Spaltenüberschrift ordnet die Spalten ebenfalls direkt neu. Sichtbarkeit und Reihenfolge werden in Ihrem Konto gespeichert, sodass die Tabelle beim nächsten Öffnen so aussieht, wie Sie sie verlassen haben.',
        'table_sort_heading' => 'Sortieren, filtern, suchen',
        'table_field_sort' => '<strong>Sortieren</strong> &mdash; klicken Sie auf eine Spaltenüberschrift, um danach zu sortieren. Klicken Sie erneut, um die Richtung umzukehren. Die aktive Sortierung wird zusammen mit dem Spaltenlayout je Analyst gespeichert.',
        'table_field_filter' => '<strong>Filter</strong> &mdash; klicken Sie auf das Trichtersymbol in einer Spaltenüberschrift, um eine Excel-artige Liste mit Kontrollkästchen für jeden in dieser Spalte tatsächlich vorkommenden Wert einzublenden. Entfernen Sie das Häkchen bei den Werten, die Sie nicht möchten; die Zahlen in der Liste zeigen, wie viele Zeilen auf jeden Wert zutreffen. Aktive Filter zeigen den Trichter violett an.',
        'table_field_search' => '<strong>Suchen</strong> &mdash; das Suchfeld in der Symbolleiste durchsucht den Text jeder sichtbaren Spalte. Es filtert während der Eingabe.',
        'table_field_reset' => '<strong>Zurücksetzen</strong> &mdash; die Schaltfläche Zurücksetzen in der Symbolleiste löscht alle Filter und das Suchfeld und setzt die Sortierung zurück.',
        'table_export_heading' => 'Rechtsklick und Export',
        'table_export_body' => 'Ein Rechtsklick auf eine Zeile öffnet dasselbe Kontextmenü wie Board und Zeitleiste &mdash; Analyst/Team zuweisen, Status/Priorität ändern. Die Schaltfläche <strong>CSV</strong> in der Symbolleiste lädt die aktuelle Ansicht (unter Berücksichtigung sichtbarer Spalten, Suche, Filter und Sortierung) als UTF-8-CSV herunter, die Excel sauber öffnet.',
        'table_tip' => 'Sortierung und Filter werden <em>nicht</em> neu ausgeführt, während Sie eine Zelle bearbeiten &mdash; das würde Ihnen den Fokus rauben. Ihre Änderung wird sofort gespeichert; wenn Sie als Nächstes die Sortierung ändern, einen Filter ändern oder auf Zurücksetzen klicken, wird der neue Wert verwendet.',
        'panel_heading' => 'Das Aufgabenpanel',
        'panel_intro' => 'Ein Klick auf eine Aufgabe öffnet rechts ein seitlich einblendendes Panel. Jedes Feld speichert automatisch, sobald Sie es ändern &mdash; es gibt keine Speichern-Schaltfläche. Das Panel des Boards ist der vollständige Editor; Kalender und Zeitleiste öffnen ein schlankeres <em>Schnellpanel</em> mit den gängigen Feldern und einem Öffnen-Symbol, das zum vollständigen Editor springt, wenn Sie eine Rich-Text-Beschreibung, Teilaufgaben oder Kommentare benötigen.',
        'panel_field_title' => '<strong>Titel</strong> &mdash; oben im Panel anklicken und eintippen.',
        'panel_field_status' => '<strong>Status &amp; Priorität</strong> &mdash; Dropdowns, die aus Ihren konfigurierten Listen erstellt werden.',
        'panel_field_assignee' => '<strong>Zugewiesen an &amp; Team</strong> &mdash; wer die Aufgabe verantwortet und zu welchem Team sie gehört.',
        'panel_field_contractor' => '<strong>Auftragnehmer &amp; Ansprechperson dort</strong> &mdash; wenn eine externe Firma die Arbeit erledigt: ein Lieferant aus Verträge und, falls gewünscht, eine Person dort. Die zugewiesene Person bleibt diejenige hier, die nachfasst. Für die Auswahl ist Zugriff auf Verträge erforderlich.',
        'panel_contractor_note' => '<strong>Auftragnehmer-Arbeit</strong> zeigt den Namen der Firma auf der Karte, und der Filter <strong>Auftragnehmer</strong> in der linken Leiste (sichtbar, sobald eine Aufgabe einen hat) schränkt das Board auf eine Firma, auf alle Aufgaben mit Auftragnehmer oder auf keine ein. Projekte können die Person in der Firma per E-Mail benachrichtigen, wenn ihr eine Aufgabe zugewiesen wird und wenn sie fällig ist &mdash; ausgeschaltet, sofern es niemand unter Projekte &rarr; Einstellungen einschaltet.',
        'panel_field_dates' => '<strong>Start- &amp; Fälligkeitsdatum</strong> &mdash; zusammen legen sie den Zeitraum fest, der im Kalender und in der Zeitleiste angezeigt wird.',
        'panel_field_tags' => '<strong>Schlagwörter</strong> &mdash; eine Auswahl mit Suche während der Eingabe; fügen Sie beliebig viele hinzu, entfernen Sie sie mit dem &times; auf jedem Chip.',
        'panel_field_desc' => '<strong>Beschreibung</strong> &mdash; ein Rich-Text-Editor mit Fettschrift, Listen und Links.',
        'panel_field_links' => '<strong>Verknüpfungen</strong> &mdash; suchen und verknüpfen Sie zugehörige Tickets oder Änderungen.',
        'panel_links_note' => '<strong>Ein Ticket und eine Änderung.</strong> Eine Aufgabe kann mit genau einem Ticket und einer Änderung verknüpft sein. Die Suchfelder bleiben deshalb sichtbar und bieten an, <em>stattdessen</em> etwas anderes zu verknüpfen. Vor dem Ersetzen wird gefragt und benannt, was entfernt würde &mdash; nichts wird ohne Ihre Zustimmung ersetzt. Dieselbe Warnung erscheint vom Ticket aus: Eine Aufgabe, die bereits zu einem anderen Ticket gehört, wird <em>verschoben</em>, und das wird vorher gesagt.',
        'panel_preview_note' => '<strong>Das &#9432; neben einem verknüpften Datensatz</strong> öffnet eine Karte mit dem Wichtigsten, ohne die Aufgabe zu verlassen &mdash; bei einem Ticket Status, Priorität, Zuständigkeit und anfragende Person; bei einer Änderung Status, Risiko und geplantes Zeitfenster. Sie ist bewusst schreibgeschützt, damit aus einem Blick keine versehentliche Änderung wird. <strong>Escape</strong> schließt sie, <strong>Öffnen</strong> führt zum Datensatz selbst. Heißt es, der Datensatz könne nicht angezeigt werden, haben Sie keinen Zugriff darauf oder es gibt ihn nicht mehr &mdash; beides wird absichtlich gleich beantwortet.',
        'panel_field_subtasks' => '<strong>Teilaufgaben</strong> &mdash; zerlegen Sie die Aufgabe in kleinere Arbeitspakete, jedes mit eigener verantwortlicher Person. Jede Zeile zeigt, wer sie hat, sowie ihre Daten für <strong>Beginn</strong> und <strong>Fällig</strong>, die Sie direkt ändern können; ziehen Sie eine Zeile am Griff <strong>&#8942;&#8942;</strong>, um die Reihenfolge zu ändern. Der Fortschritt wird auf der übergeordneten Karte angezeigt, die Teilaufgaben darunter aufgelistet.',
        'panel_field_comments' => '<strong>Kommentare</strong> &mdash; ein fortlaufender Diskussionsverlauf zur Aufgabe.',
        'panel_field_work' => '<strong>Arbeitsbeginn &amp; -ende</strong> &mdash; wann die Aufgabe bearbeitet werden <em>soll</em>, mit einer Option <strong>Ganztägig</strong>. Diese Zeiten gelten für alle gleich: 14 Uhr ist 14 Uhr, egal wer sie liest &mdash; wie ein Wartungsfenster.',
        'panel_field_time' => '<strong>Zeit</strong> &mdash; wie lange die Arbeit tatsächlich gedauert hat, als einzelne Sitzungen mit jeweils einer Notiz erfasst und summiert. Eine übergeordnete Aufgabe zeigt zusätzlich die Summe <em>inklusive ihrer Unteraufgaben</em>. Erfasste Zeit ist ein echter Zeitpunkt und erscheint daher in Ihrer eigenen Zeitzone.',
        'panel_view_note' => 'Die Aufgabe öffnet sich in einem Bereich am Rand des Boards. Mit der Schaltfläche <strong>Erweitern</strong> in dessen Ecke öffnen Sie ein großes Fenster, das denselben Inhalt in zwei Spalten darstellt &mdash; Beschreibung und Kommentare links, die kurzen Felder rechts. Im großen Fenster wechselt eine zweite Schaltfläche stattdessen zu <strong>Registerkarten</strong>: Details, Teilaufgaben, Zeit, Kommentare, Verknüpfungen und Dokumente, jeweils mit der Anzahl der enthaltenen Einträge. FreeITSM merkt sich Ihre Vorliebe, und Sie können sie auch unter <em>Einstellungen &rarr; Aufgabe öffnen</em> festlegen.',
        'panel_context_note' => '<strong>Klicken Sie mit der rechten Maustaste auf eine Karte</strong>, um das meiste davon zu erreichen, ohne die Aufgabe zu öffnen: öffnen, sich selbst oder jemand anderem zuweisen, Status oder Priorität ändern, ein Fälligkeitsdatum setzen, als erledigt markieren, Zeit erfassen, eine Teilaufgabe anlegen, einen Link kopieren oder sie löschen.',
        'panel_delete_note' => 'Die Löschen-Schaltfläche (oben rechts im Panel) entfernt die Aufgabe und alle ihre Teilaufgaben &mdash; zuvor wird eine Bestätigung abgefragt.',
        'nav_repeats' => 'Wiederkehrende Aufgaben',
        'repeats_heading' => 'Wiederkehrende Aufgaben',
        'repeats_intro' => 'Manche Arbeit kommt immer wieder: eine monatliche Sicherungsprüfung, eine vierteljährliche Zugriffsprüfung, ein wöchentlicher Bericht. Jede Aufgabe kann wiederholt werden, und FreeITSM erstellt die nächste Wiederholung für Sie, statt dass Sie daran denken müssen.',
        'repeats_cron_warning' => '<strong>Ein fester Zeitplan braucht einen geplanten Job auf dem Server, und nichts warnt Sie, wenn er fehlt.</strong> Wiederholungen mit <em>nach festem Zeitplan</em> werden von <code>cron/task_recurrence.php</code> erstellt. Eine frische Installation hat überhaupt keine geplanten Aufgaben, daher erzeugt ein fester Zeitplan so lange nichts, bis jemand dies einrichtet &mdash; kein Fehler, kein Protokolleintrag, nur eine Wiederholung, die stillschweigend nichts tut. Führen Sie ihn <strong>einmal täglich</strong> aus. Unter <strong>Reporting &rarr; Systemprotokolle &rarr; Hintergrundjobs</strong> sehen Sie, ob er läuft. Wiederholungen mit <em>nachdem diese abgeschlossen wurde</em> sind nicht betroffen: Sie werden innerhalb der Anfrage erstellt, die die vorherige abschließt, und funktionieren daher auf einer Installation ganz ohne geplante Aufgaben.',
        'repeats_setup_heading' => 'Einrichten',
        'repeats_setup_body' => 'Öffnen Sie eine Aufgabe und suchen Sie im Bereich <strong>Wiederholungen</strong> die Schaltfläche <strong>Wiederholung einrichten</strong>. Sie können auch mit der rechten Maustaste auf eine Karte im Board klicken und <strong>Wiederholung einrichten</strong> wählen, ohne die Aufgabe zu öffnen. Eine Teilaufgabe kann sich nicht eigenständig wiederholen &mdash; eine Wiederholung gehört zur Arbeit selbst, nicht zu einem Schritt darin.',
        'repeats_mode_heading' => 'Zwei Arten der Wiederholung, und der Unterschied zählt',
        'repeats_mode_body' => 'Das ist die erste Wahl im Editor und die, über die es sich nachzudenken lohnt, denn beide verhalten sich unterschiedlich, wenn die Arbeit in Verzug gerät.',
        'repeats_mode_completion' => '<strong>Nach Abschluss dieser Aufgabe</strong> &mdash; die nächste Wiederholung erscheint, wenn Sie die aktuelle abschließen, und ihr Termin zählt ab dem Tag, an dem Sie tatsächlich fertig waren. Das meinen die meisten mit &bdquo;monatlicher Prüfung&ldquo;: Wird die Prüfung im Februar am 5. erledigt, fällt die im März auf einen Monat nach dem 5. Solange die aktuelle offen ist, wird nichts erstellt, Sie haben also nie zwei gleiche Aufgaben wartend.',
        'repeats_mode_schedule' => '<strong>Nach festem Zeitplan</strong> &mdash; die Wiederholungen kommen zu ihren Terminen, unabhängig davon, ob die vorherige abgeschlossen wurde. Das braucht eine Compliance-Prüfung: Das März-Audit ist im März fällig, auch wenn das für Februar nie stattgefunden hat. Verpasste Wiederholungen sammeln sich an, statt still übersprungen zu werden, und wenn der Server eine Woche aus war, holt der Task sie nach.',
        'repeats_pattern_heading' => 'Wie oft',
        'repeats_pattern_body' => 'Ein Muster besteht aus einer Häufigkeit und einem Intervall &mdash; alle N Tage, Wochen, Monate oder Jahre &mdash; sowie, bei wöchentlichen und monatlichen Wiederholungen, aus der Wahl der Tage.',
        'repeats_pattern_daily' => '<strong>Täglich</strong> &mdash; jeden Tag oder alle N Tage.',
        'repeats_pattern_weekly' => '<strong>Wöchentlich</strong> &mdash; jede Woche oder alle N Wochen, an beliebigen Wochentagen. &bdquo;Jede zweite Woche montags und donnerstags&ldquo; ist eine einzige Regel, nicht zwei.',
        'repeats_pattern_dom' => '<strong>Monatlich, nach Tagesnummer</strong> &mdash; der 1., der 15., der 28. Geben Sie <strong>-1</strong> für den letzten Tag des Monats ein, unabhängig von dessen Länge &mdash; das braucht die Monatsabschlussarbeit und lässt sich nicht als Zahl schreiben. Eine Tagesnummer, die länger ist als ein kurzer Monat &mdash; der 31. im Februar &mdash; fällt auf den letzten Tag dieses Monats zurück, statt den Monat zu überspringen.',
        'repeats_pattern_nth' => '<strong>Monatlich, nach benanntem Wochentag</strong> &mdash; der erste Montag, der dritte Mittwoch, der letzte Freitag. Wählen Sie Position und Wochentag. Wird der fünfte eines Wochentags in einem Monat verlangt, der nur vier hat, wird auf den letzten zurückgegriffen, sodass der Monat nie ausfällt.',
        'repeats_pattern_yearly' => '<strong>Jährlich</strong> &mdash; jedes Jahr oder alle N Jahre, wahlweise in einem bestimmten Monat, mit derselben Wahl nach Tagesnummer oder benanntem Wochentag wie monatlich.',
        'repeats_ends_heading' => 'Wann sie endet',
        'repeats_ends_never' => '<strong>Nie</strong> &mdash; sie läuft weiter, bis Sie sie beenden.',
        'repeats_ends_date' => '<strong>An einem Datum</strong> &mdash; die letzte Wiederholung ist die letzte, die auf oder vor dieses Datum fällt.',
        'repeats_ends_count' => '<strong>Nach einer Anzahl von Wiederholungen</strong> &mdash; die Anzahl <em>schließt</em> die Aufgabe ein, an der Sie die Wiederholung eingerichtet haben. Fünf ergibt die vorliegende Aufgabe plus vier weitere.',
        'repeats_carry_heading' => 'Was übernommen wird',
        'repeats_carry_body' => 'Beschreibung, Teilaufgaben, zugewiesene Person, Schlagwörter, Verknüpfungen zu Tickets und Änderungen sowie angehängte Dokumente werden einzeln gewählt, denn die richtige Antwort hängt von der Aufgabe ab. Anhänge zu übernehmen ist richtig für eine Checkliste, die jeden Monat dieselben Formulare nutzt, und falsch für ein Audit, das jedes Mal frische Nachweise sammeln soll.',
        'repeats_carry_note' => 'Eine neue Wiederholung kommt immer offen und unerledigt an, nie in dem Status, in dem die vorherige abgeschlossen wurde. Sie behält auch den Abstand zwischen Start- und Fälligkeitsdatum, sodass aus zwei Wochen Arbeit weiterhin zwei Wochen werden.',
        'repeats_when_heading' => 'Wann die nächste erscheint',
        'repeats_when_body' => 'Eine Wiederholung wird erstellt, wenn die Arbeit daran <strong>beginnen</strong> kann, nicht wenn sie fällig wird. Eine Aufgabe, deren Startdatum zwei Wochen vor dem Fälligkeitsdatum liegt, erscheint zwei Wochen im Voraus; eine Aufgabe mit nur einem Fälligkeitsdatum erscheint am Tag selbst. Es gibt bewusst keine Einstellung für &bdquo;Tage Vorlauf&ldquo;: Der Vorlauf ist die Dauer, die Sie der Aufgabe bereits gegeben haben, und das ist eine bessere Antwort als eine Zahl, die für die Hälfte der Aufgaben falsch wäre.',
        'repeats_when_note' => 'Deshalb enthält das Board immer nur Arbeit, die Sie jetzt tatsächlich tun könnten. Künftige Wiederholungen eines festen Zeitplans sind trotzdem im <strong>Kalender</strong> sichtbar, blass gezeichnet und ohne Aufgabe dahinter, sodass Sie den Plan sehen, ohne dass sich das Board mit Aufgaben füllt, die niemand beginnen kann.',
        'repeats_preview_heading' => 'Vorschau',
        'repeats_preview_body' => '&bdquo;Jeden zweiten Dienstag im Monat, fünfmal&ldquo; ist kein Satz, den die meisten im Kopf in Termine übersetzen können. <strong>Vorschau</strong> neben Speichern listet jede Wiederholung auf, die die aktuellen Einstellungen erzeugen würden, mit Start- und Fälligkeitsdatum &mdash; auch für noch nicht gespeicherte Einstellungen, sodass Sie eine Regel ausprobieren können, bevor Sie sie behalten. Die vorliegende Aufgabe wird als erste Wiederholung gezeigt, und bereits vorhandene sind markiert; so zeigt die Vorschau einer bestehenden Wiederholung auch, was sie bereits getan hat. Eine Wiederholung ohne Ende zeigt die ersten 25.',
        'repeats_preview_note' => 'Erzeugen die Einstellungen gar nichts, sagt die Vorschau das deutlich &mdash; meist ein Hinweis darauf, dass das Ende oder der gewählte Tag nicht das ist, was Sie gemeint haben. Eine Wiederholung nach Abschluss hat keine Termine zum Auflisten, denn ihr nächster Termin zählt ab dem Tag, an dem die Arbeit tatsächlich fertig ist; die Vorschau erklärt das, statt zu raten.',
        'repeats_finding_heading' => 'Sich in einer Serie zurechtfinden',
        'repeats_finding_body' => 'Eine Aufgabe, die zu einer Wiederholung gehört, trägt im Board und im Kalender ein kleines Wiederholungssymbol, und im Bereich zeigt sie ihre Position in der Serie &mdash; <em>Wiederholung 3 von 12</em>. Der Bereich enthält außerdem einen Link zurück zu der Aufgabe, mit der die Serie begonnen hat, sodass das Original von jeder Wiederholung aus einen Klick entfernt ist.',
        'repeats_stop_heading' => 'Eine Wiederholung beenden',
        'repeats_stop_body' => '<strong>Wiederholung beenden</strong> beendet die Serie und löscht nie etwas. Bereits erstellte Wiederholungen sind echte Arbeit, teils erledigt; eine Wiederholung abzuschalten bedeutet also &bdquo;keine weiteren davon&ldquo; und nicht &bdquo;so tun, als hätte es die letzten sechs Monate nicht gegeben&ldquo;. Die Einstellungen zu ändern und erneut zu speichern ersetzt die Regel für künftige Wiederholungen und lässt bestehende unangetastet.',
        'repeats_tip' => 'Unsicher, welchen Modus Sie brauchen? Soll eine Verzögerung die nächste nach hinten schieben, wählen Sie <em>nach Abschluss dieser Aufgabe</em>. Soll eine Verzögerung dazu führen, dass zwei zu erledigen sind, wählen Sie <em>nach festem Zeitplan</em>.',
        'tags_heading' => 'Schlagwörter',
        'tags_intro' => 'Schlagwörter sind mehrfach vergebbare Bezeichnungen für übergreifende Themen &mdash; Dinge, die nicht in einen Status oder eine Priorität passen. Eine Aufgabe kann beliebig viele davon tragen.',
        'tags_body1' => 'Der Status beantwortet "in welcher Phase ist das?", die Priorität beantwortet "wie dringend?", und ein Schlagwort beantwortet "<em>worum</em> geht es dabei?" &mdash; Sicherheit, ISO, Umwelt und so weiter. Da eine Aufgabe mehrere Schlagwörter tragen kann, können Sie Ihre Arbeit themenweise über alle Status und Verantwortlichen hinweg aufschlüsseln.',
        'tags_body2' => 'Schlagwörter werden unter Einstellungen &rarr; Schlagwörter verwaltet, jedes mit einem Namen und einer Farbe. Fünf Anzeigeoptionen dort legen fest, ob Schlagwörter aus einer Aufgabe heraus erstellt werden können und wo sie erscheinen &mdash; Karten-Chips, der Seitenleisten-Filter, die Suche und Kalender/Zeitleiste.',
        'tags_tip' => 'Ein Schlagwort ist der richtige Platz für ein "irgendwann/vielleicht"-Thema. Versehen Sie eine Handvoll Ideen mit dem Schlagwort <em>Blue Sky</em>, und Sie können sie jederzeit über den Schlagwort-Filter aufrufen, ohne eine eigene Spalte zu benötigen.',
        'settings_heading' => 'Einstellungen',
        'settings_intro' => 'Die Seite Einstellungen hat für jeden Bereich einen Tab, und Sie sehen die Tabs, die Ihre Rolle ändern darf. Einstellungen gelten für die gesamte Installation: Eine Änderung hier prägt Board, Kalender und Karten für das ganze Team, nicht nur für Sie.',
        'settings_lookups_heading' => 'Status &amp; Prioritäten',
        'settings_lookups_body' => 'Diese beiden Tabs verwalten die Auswahllisten, auf die jede Aufgabe zurückgreift. Jede Zeile hat einen Namen, eine Farbe und eine Anzeigereihenfolge; Sie fügen Zeilen mit den Schaltflächen rechts hinzu, bearbeiten oder löschen sie.',
        'settings_field_statuses' => '<strong>Status</strong> &mdash; die Workflow-Zustände, die zugleich als Board-Spalten dienen (in Anzeigereihenfolge angezeigt). Ein Status ist der <em>Standard</em> für neue Aufgaben. Ein als <em>Geschlossen</em> markierter Status gilt als erledigt &mdash; Aufgaben, die dorthin verschoben werden, erhalten einen Abschlusszeitpunkt und fallen aus den Zählern offener Aufgaben heraus. Ein Status kann auch auf inaktiv gesetzt werden, um ihn außer Gebrauch zu nehmen, ohne die Historie zu verlieren.',
        'settings_field_priorities' => '<strong>Prioritäten</strong> &mdash; die Prioritätsstufen, die als farbiger Punkt auf jeder Karte angezeigt werden. Eine Priorität ist der Standard für neue Aufgaben.',
        'settings_card_heading' => 'Karte',
        'settings_card_body' => 'Der Tab Karte enthält eine Reihe von Kontrollkästchen, die festlegen, welche zusätzlichen Details auf jeder Board- und Listenkarte erscheinen, damit Sie Aufgaben überfliegen können, ohne sie zu öffnen: Prioritätspunkt, Initialen des Zugewiesenen, Team, Startdatum, Fälligkeitsdatum, ein Beschreibungsauszug, Teilaufgaben-Fortschritt und die Anzeige verknüpfter Elemente. Der Aufgabentitel wird immer angezeigt. Änderungen werden beim nächsten Laden des Boards wirksam.',
        'settings_calendar_heading' => 'Kalenderoptionen',
        'settings_calendar_body' => 'Der Tab Kalender hat eine einzige Entscheidung: wie eine <strong>mehrtägige Aufgabe</strong> &mdash; eine, deren Startdatum vor dem Fälligkeitsdatum liegt &mdash; im Aufgabenkalender dargestellt wird. Wählen Sie einen von drei Modi:',
        'settings_calendar_deadline' => '<strong>Fälligkeitsmarkierung</strong> (der Standard) &mdash; die Aufgabe erscheint einmal, als einzelner Chip an ihrem Fälligkeitsdatum. Das hält den Kalender auf das Anstehende fokussiert statt auf Dauern und ist die übersichtlichste Wahl bei vielen Aufgaben. Der gesamte Zeitraum bleibt in der Zeitleiste sichtbar.',
        'settings_calendar_span' => '<strong>Durchgehender Balken</strong> &mdash; die Aufgabe wird als durchgehender Balken vom Start- bis zum Fälligkeitsdatum gezeichnet, der am Ende jeder Woche in die nächste Zeile umbricht. Balken stapeln sich in Bahnen, sodass sie sich nie überschneiden. Am besten geeignet, wenn es wichtiger ist zu sehen, wie lange etwas dauert und was sich überschneidet, als ein übersichtliches Raster zu haben.',
        'settings_calendar_everyday' => '<strong>Jeden Tag</strong> &mdash; ein Chip wird in jeder einzelnen Tageszelle wiederholt, die die Aufgabe abdeckt. Die gründlichste Variante &mdash; die Aufgabe ist an keinem Tag zu übersehen &mdash;, aber schon wenige lange Aufgaben können das Raster schnell überfüllen.',
        'settings_calendar_note' => 'Unabhängig vom gewählten Modus wird eine Aufgabe mit <em>nur</em> einem Fälligkeitsdatum (ohne Startdatum) immer als einzelner Chip an diesem Datum angezeigt &mdash; die Modi ändern nur, wie ein echter Datums<em>zeitraum</em> gezeichnet wird. Der Kalender selbst zeigt den aktuellen Modus in seiner Symbolleiste, mit einem <strong>Ändern</strong>-Link direkt zurück zu diesem Tab.',
        'settings_checklists_heading' => 'Checklisten',
        'settings_checklists_body' => 'Aktivieren Sie <strong>Checklisten bei Aufgaben erlauben</strong>, und jede Aufgabe und Teilaufgabe erhält einen Abschnitt <strong>Checkliste</strong>: Hängen Sie eine beliebige Checkliste aus dem Modul Checklisten an, die für <em>Aufgaben</em> oder <em>Beides</em> gilt, und haken Sie deren Schritte beim Arbeiten ab. Ein Schritt, der einen Wert verlangt, lässt sich nicht ohne einen abhaken. Standardmäßig ist die Funktion ausgeschaltet. Eine Aufgabe kann mehr als eine Checkliste tragen; ziehen Sie eine Checkliste oder einen Schritt darin am Griff <strong>&#8942;&#8942;</strong>, um die Reihenfolge zu ändern.',
        'settings_checklists_standard' => '<strong>Standard</strong>-Checkliste &mdash; Sie können die Aufgabe weiterhin mit offenen Pflichtschritten abschließen. Sie werden vorher gefragt, und der Verlauf der Aufgabe hält fest, wer sie abgeschlossen hat und welche Schritte übersprungen wurden.',
        'settings_checklists_critical' => '<strong>Kritische</strong> Checkliste (Vorhängeschloss) &mdash; die Aufgabe kann erst abgeschlossen werden, wenn ihre Pflichtschritte erledigt sind, sei es über das Statusfeld, durch Ziehen der Karte in eine geschlossene Spalte, durch Abhaken einer Teilaufgabe oder über die API.',
        'settings_evidence_heading' => 'Nachweis',
        'settings_evidence_body' => 'Vier Entscheidungen zu dem Datensatz, den ein Auditor liest. Jede ist standardmäßig auf die nachsichtige Variante gesetzt, und wie Sie auch wählen, nichts bereits Erfasstes geht verloren.',
        'settings_evidence_checklist' => '<strong>Checkliste einer abgeschlossenen Aufgabe ändern</strong> - <em>erlaubt und protokolliert</em> (ein Tippfehler kann korrigiert werden; die Änderung wird im Bericht gekennzeichnet) oder <em>abgelehnt, bis die Aufgabe wieder geöffnet wird</em>.',
        'settings_evidence_delete' => '<strong>Eine Durchführung einer Wiederholung löschen</strong> - <em>erlaubt und als Entfernt aufbewahrt</em> (eine eingefrorene Kopie bleibt im Bericht) oder <em>nicht erlaubt - stattdessen überspringen</em>.',
        'settings_evidence_skip' => '<strong>Status, in den eine übersprungene Durchführung wechselt</strong> - einer Ihrer geschlossenen Status; standardmäßig der letzte in Ihrer Reihenfolge, auf einer Standardinstallation <em>Abgebrochen</em>.',
        'settings_evidence_access' => '<strong>Wer den Nachweisbericht ausführen darf</strong> - alle, die die wiederkehrende Aufgabe sehen können, oder nur Rollen mit <em>Nachweisbericht ausführen</em>.',
        'settings_checklists_note' => 'Die Unternehmenseinstellung <strong>Alle blockieren</strong> unter Tickets &rarr; Einstellungen &rarr; Checklisten gilt auch für Aufgaben. Eine wiederkehrende Aufgabe erhält bei jedem neuen Auftreten eine frische Kopie ihrer Checklisten ohne Häkchen. Das Ausschalten blendet den Abschnitt aus und beendet die Durchsetzung; es löscht nie eine Checkliste.',
        'settings_tags_heading' => 'Schlagwort-Optionen',
        'settings_tags_body' => 'Der Tab Schlagwörter erfüllt zwei Aufgaben. Die obere Hälfte ist die <strong>Schlagwortliste</strong> &mdash; fügen Sie die Schlagwörter, die Ihr Team verwenden kann, hinzu, bearbeiten, löschen oder färben Sie sie um (jedes besteht einfach aus einem Namen und einer Farbe). Die untere Hälfte, <strong>Anzeigeoptionen</strong>, umfasst fünf Schalter, die festlegen, wie das Taggen funktioniert und wo Schlagwörter erscheinen:',
        'settings_tags_allow' => '<strong>Neue Schlagwörter aus einer Aufgabe erlauben</strong> (standardmäßig aus) &mdash; der Schalter zwischen verwaltet und offen. Aus: Die Schlagwortliste ist ein fester Wortschatz: Analysten können nur vorhandene Schlagwörter auswählen, neue werden hier in den Einstellungen hinzugefügt &mdash; am besten für einen kontrollierten Bestand wie Sicherheit oder ISO. An: In der Schlagwort-Auswahl einer Aufgabe kann ein Analyst zusätzlich ein brandneues Schlagwort eintippen und direkt erstellen.',
        'settings_tags_chips' => '<strong>Karten-Chips</strong> &mdash; zeigt farbige Schlagwort-Chips auf Board- und Listenkarten an. Schalten Sie dies aus, wenn Sie Karten lieber minimal halten möchten.',
        'settings_tags_filter' => '<strong>Seitenleisten-Filter</strong> &mdash; zeigt ein Schlagwort-Dropdown in der Board-/Listen-Seitenleiste an, mit dem Sie die Ansicht auf ein einzelnes Schlagwort eingrenzen können.',
        'settings_tags_search' => '<strong>In Suche einbeziehen</strong> &mdash; bezieht Schlagwortnamen in die Suche ein, sodass die Eingabe eines Schlagwortnamens jede Aufgabe findet, die es trägt.',
        'settings_tags_calendar' => '<strong>Kalender &amp; Zeitleiste</strong> &mdash; zeigt kleine Schlagwort-Punkte auf Aufgabenbalken in Kalender- und Zeitleistenansicht an. Standardmäßig aus, da diese Ansichten auf Termine fokussiert sind.',
        'settings_tags_note' => 'Die Schalter sind unabhängig voneinander &mdash; Sie können zum Beispiel Schlagwörter von den Karten fernhalten, aber trotzdem danach filtern und suchen. Änderungen an der Schlagwort-Anzeige werden beim nächsten Laden einer Ansicht wirksam.',
        'tips_heading' => 'Schnelltipps',
        'tips_intro' => 'Ein paar Abkürzungen und Gewohnheiten, die den Umgang mit dem Modul schneller machen.',
        'tip1' => '<strong>Rechtsklick ist schneller.</strong> Weisen Sie eine Karte über ihr Kontextmenü neu zu oder ändern Sie die Priorität, ohne sie zu öffnen.',
        'tip2' => '<strong>Schnellerfassung, dann Eingabetaste.</strong> Erfassen Sie einen Aufgabentitel über die +-Schaltfläche der Spalte und füllen Sie die Details später aus.',
        'tip3' => '<strong>Die Suche ist sofort.</strong> Sie filtert während der Eingabe und findet jedes Wort &mdash; kein Warten, keine Eingabetaste nötig.',
        'tip4' => '<strong>Mit Schlagwörtern nach Themen.</strong> Verwenden Sie Schlagwörter für alles, was Status übergreift &mdash; Compliance, Sicherheit, Projekte.',
        'tip5' => '<strong>Zwei Termine, zwei Ansichten.</strong> Legen Sie ein Start- und ein Fälligkeitsdatum fest, und die Aufgabe zeichnet sich selbst sowohl im Kalender als auch in der Zeitleiste ein.',
        'tip6' => '<strong>Die Quelle verknüpfen.</strong> Hängen Sie das Ticket oder die Änderung an, aus dem bzw. der eine Aufgabe entstanden ist, damit der Kontext nur einen Klick entfernt ist.',
        'tip7' => '<strong>Den Balken ziehen.</strong> Ziehen Sie in der Zeitleiste den Körper, um zu verschieben, und ziehen Sie einen der Ränder, um Start- oder Fälligkeitsdatum direkt festzulegen &mdash; kein Panel nötig.',
        'tip8' => '<strong>Bauen Sie sich Ihre eigene Tabelle.</strong> Wählen Sie in der Tabellenansicht, welche Spalten angezeigt werden, ziehen Sie sie in die gewünschte Reihenfolge, sortieren und filtern Sie &mdash; Ihr Layout wird je Analyst gespeichert.',
    ],
